-- hyprland-plugins is generated by Nix and loads hy3 with the correct store path
require("hyprland-plugins")

-- Run `hyprctl monitors` in Hyprland to confirm connector names;
-- Wayland names may differ from X11 (e.g. HDMI-A-1 instead of HDMI-0).
hl.monitor({
  output    = "HDMI-A-2",  -- Huawei AD80HW
  mode      = "1920x1080",
  position  = "0x548",
  scale     = 1,
  transform = 1,           -- rotate left (90° CCW)
})
hl.monitor({
  output    = "DP-2",      -- LG ULTRAGEAR
  mode      = "2560x1440@180",
  position  = "1080x1080",
  scale     = 1,
  transform = 0,
})
hl.monitor({
  output    = "DP-3",      -- LG ULTRAWIDE
  mode      = "2560x1080",
  position  = "1080x0",
  scale     = 1,
  transform = 2,           -- inverted (180°)
})
-- fallback for any other connected monitor
hl.monitor({
  output   = "",
  mode     = "preferred",
  position = "auto",
  scale    = "auto",
})

hl.config({
  general = {
    layout      = "hy3",
    gaps_in     = 5,
    gaps_out    = 10,
    border_size = 2,
  },
  decoration = {
    rounding = 6,
    blur = { enabled = true, size = 3, passes = 1 },
  },
  input = {
    kb_layout    = "us",
    follow_mouse = 1,
    sensitivity  = 0,
  },
  misc = {
    force_default_wallpaper = 0,
    disable_hyprland_logo   = true,
  },
})

hl.window_rule({
  name  = "calendar-popup",
  match = { class = "cal%-popup" },
  float = true,
  size  = "560 240",
  center = true,
  pin   = true,
})

hl.on("hyprland.start", function()
  hl.exec_cmd("dbus-update-activation-environment --systemd DISPLAY HYPRLAND_INSTANCE_SIGNATURE WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
  hl.exec_cmd("dunst")
  hl.exec_cmd("swww-daemon")
  hl.exec_cmd("swww img ~/.wallpapers/landscape0.png")
  hl.exec_cmd("bash -c 'waybar &'")
end)

local mod = "SUPER"

hl.bind(mod .. " + Return",        hl.dsp.exec_cmd("wezterm"))
hl.bind(mod .. " + T",             hl.dsp.exec_cmd("wezterm"))
hl.bind(mod .. " + D",             hl.dsp.exec_cmd("rofi -show drun"))
hl.bind(mod .. " + Q",             hl.dsp.window.close())
hl.bind(mod .. " + F",             hl.dsp.window.fullscreen())
hl.bind(mod .. " + SHIFT + Space", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mod .. " + SHIFT + E",     hl.dsp.exit())

-- hy3 focus (vim keys)
hl.bind(mod .. " + H", hl.dsp.exec_cmd("hyprctl dispatch hy3:movefocus l"))
hl.bind(mod .. " + L", hl.dsp.exec_cmd("hyprctl dispatch hy3:movefocus r"))
hl.bind(mod .. " + K", hl.dsp.exec_cmd("hyprctl dispatch hy3:movefocus u"))
hl.bind(mod .. " + J", hl.dsp.exec_cmd("hyprctl dispatch hy3:movefocus d"))

-- hy3 move window
hl.bind(mod .. " + SHIFT + H", hl.dsp.exec_cmd("hyprctl dispatch hy3:movewindow l"))
hl.bind(mod .. " + SHIFT + L", hl.dsp.exec_cmd("hyprctl dispatch hy3:movewindow r"))
hl.bind(mod .. " + SHIFT + K", hl.dsp.exec_cmd("hyprctl dispatch hy3:movewindow u"))
hl.bind(mod .. " + SHIFT + J", hl.dsp.exec_cmd("hyprctl dispatch hy3:movewindow d"))

-- hy3 splits
hl.bind(mod .. " + V",      hl.dsp.exec_cmd("hyprctl dispatch hy3:makegroup v"))
hl.bind(mod .. " + B",      hl.dsp.exec_cmd("hyprctl dispatch hy3:makegroup h"))
hl.bind(mod .. " + W",      hl.dsp.exec_cmd("hyprctl dispatch hy3:makegroup tab"))
hl.bind(mod .. " + E",      hl.dsp.exec_cmd("hyprctl dispatch hy3:makegroup opposite"))
hl.bind(mod .. " + Period", hl.dsp.exec_cmd("hyprctl dispatch hy3:changegroupactive f"))
hl.bind(mod .. " + Comma",  hl.dsp.exec_cmd("hyprctl dispatch hy3:changegroupactive b"))

-- workspaces
for i = 1, 10 do
  local key = i % 10
  hl.bind(mod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
  hl.bind(mod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- mouse drag / resize
hl.bind(mod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- apps (Super+B skipped — conflicts with hy3:makegroup h)
hl.bind(mod .. " + S",       hl.dsp.exec_cmd("~/.config/rofi/tmux.sh"))
hl.bind(mod .. " + Tab",     hl.dsp.exec_cmd("~/.config/rofi/window.sh"))
hl.bind(mod .. " + Escape",  hl.dsp.exec_cmd("swaylock"))

-- dunst
hl.bind(mod .. " + M", hl.dsp.exec_cmd("dunstctl set-paused toggle"))
hl.bind(mod .. " + N", hl.dsp.exec_cmd("dunstctl close-all"))

-- audio
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pamixer -i 5"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pamixer -d 5"))
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("pamixer -t"))

-- screenshot: select region → clipboard
hl.bind("Print", hl.dsp.exec_cmd([[bash -c 'grim -g "$(slurp)" - | wl-copy']]))